// scrolls left through the list and updates to show the new indexed win condition
onEvent("leftButton", "click", function(){
  if(index > 0){
    index = index - 1;
  }
  updateScreen();
});

// scrolls right through the list and updates to show the new indexed win condition
onEvent("rightButton", "click", function(){
  if(index < winConList.length-1){
    index = index + 1;
  }
  updateScreen();
});

/* 
* selects currently indexed win condition (WinCon = winConList[index];)
* prints the selected win condition to console
*
* sets the text of finalWinConLabel based on current string value of winCon
* hides the scrolling win condition list since user has selected
* shows the final win condition textbox to show user selection

* fills deckLabel with the proper deck (via the for loop traversal)
* hides select button to fix a cosmetic bug involving the lists
* updates screen to show changes
*/
onEvent("selectButton", "click", function(winCon){
  winConSelected = true;
  winCon = winConList[index];
  if (winConSelected === true){
    console.log("Selected? " + winConSelected);
  }
  console.log("Win condition selected: " + winCon); 
  
  setText("finalWinConLabel", winCon);
  hideElement("winConLabel");
  showElement("finalWinConLabel");
  
  for (var i = 0; i < winConList.length; i++){
    if (winConList[i] === winCon){
      setText("deckLabel", deckList[i]);
    }
  }
  hideElement("selectButton");
  updateScreen();
});

// updates screen to show currently indexed win condition, and or to show the full deck
function updateScreen(){
  setProperty("winConLabel", "text", winConList[index]);
  setText("winConLabel", winConList[index]);
  if(winConSelected === false){
    setProperty("winConImage", "image", winConImages[index]);
  }
}
